//! G6-0 (M1-0) — native replay of the `game_loop` integration vectors.
//!
//! `data/m1_vectors.rs` is generated by `tools/gen_m1_vectors.mjs`, which
//! drives the REAL TS `GameMapImpl` + `WaterManager` over synthetic terrain
//! bytes and pins the per-op result stream. Every f64 comparison goes through
//! `to_bits()` — a single-ULP drift fails loudly.

#[path = "data/m1_vectors.rs"]
mod m1_vectors;

use openfront_core::game_loop::GameLoopHarness;

#[test]
fn m1_integration_scenarios_match_ts() {
    for s in m1_vectors::M1_SCENARIOS {
        let mut h = GameLoopHarness::default();
        assert_eq!(
            s.ops.len(),
            s.res.len(),
            "scenario {}: op/res count mismatch",
            s.name
        );
        for (i, op) in s.ops.iter().enumerate() {
            let got = h.run_op(op.kind, op.args);
            let want = s.res[i];
            assert_eq!(
                got.len(),
                want.len(),
                "scenario {} op #{} (kind {}): length {} vs TS {}",
                s.name,
                i,
                op.kind,
                got.len(),
                want.len()
            );
            for (k, (&g, &w)) in got.iter().zip(want.iter()).enumerate() {
                let (gb, wb) = (g.to_bits(), w.to_bits());
                assert_eq!(
                    gb, wb,
                    "scenario {} op #{} (kind {}) token {k}: got {g:?} (bits {gb:#018x}), TS bits {wb:#018x}",
                    s.name, i, op.kind
                );
            }
        }
    }
}
